import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:usque/models/app_models.dart';
import 'package:usque/models/scenarios.dart';

/// Generated by the usque-core scene contract test. Rust owns the scene field
/// set; this checks that the GUI projection neither drops nor invents fields.
Map<String, Object?> _fixture(String name) {
  final source = File(
    'test/fixtures/scenario_settings_contract.json',
  ).readAsStringSync();
  return Map<String, Object?>.from(
    (jsonDecode(source) as Map<String, Object?>)[name] as Map,
  );
}

bool _empty(Object? value) =>
    value == null ||
    value == '' ||
    value == 0 ||
    (value is List && value.isEmpty);

/// Rust omits empty optional fields. Drop only such extra GUI keys; a missing
/// key, a renamed value or a non-empty extra key still fails.
Object? _canonical(Object? value, Object? expected) {
  if (value is Map && expected is Map) {
    return {
      for (final entry in value.entries)
        if (expected.containsKey(entry.key) || !_empty(entry.value))
          entry.key: _canonical(entry.value, expected[entry.key]),
    };
  }
  if (value is List && expected is List && value.length == expected.length) {
    return [
      for (var i = 0; i < value.length; i++) _canonical(value[i], expected[i]),
    ];
  }
  return value;
}

void main() {
  test('scene snapshots require the complete current field set', () {
    final settings = _fixture('default');
    for (final field in ScenarioSettings.managedFields) {
      final missing = Map<String, Object?>.from(settings)..remove(field);
      expect(() => ScenarioSettings(missing), throwsFormatException);
    }
    expect(
      () => ScenarioSettings({...settings, 'endpoint': null}),
      throwsFormatException,
    );
    expect(
      () => ScenarioSettings({...settings, 'endpoint': <String, Object?>{}}),
      throwsFormatException,
    );
  });

  test('former scene globals are rejected instead of silently discarded', () {
    final settings = _fixture('default');
    for (final field in [
      'frontends',
      'allow_lan',
      'routing',
      'geo_direct_countries',
      'direct_dns',
      'warp_dns',
      'dns_mode',
      'dns_servers',
      'proxy_system_proxy',
      'proxy_dns_mode',
      'proxy_dns_servers',
    ]) {
      expect(
        () => ScenarioSettings({...settings, field: null}),
        throwsFormatException,
      );
    }
  });

  test(
    'scene preset accepts null but never inherits a malformed empty region',
    () {
      final settings = _fixture('default');
      final endpoint = Map<String, Object?>.from(settings['endpoint']! as Map);
      final base = UsqueProfile.defaultProfile().copyWith(
        endpointPresetRegion: EndpointPresetRegion.fi,
      );
      expect(
        ScenarioSettings(settings).toProfile(base).endpointPresetRegion,
        isNull,
      );
      expect(
        () => ScenarioSettings({
          ...settings,
          'endpoint': {...endpoint, 'preset_region': ''},
        }).toProfile(base),
        throwsArgumentError,
      );
    },
  );

  for (final name in ['default', 'sample']) {
    test('$name scene settings survive the GUI profile projection', () {
      final expected = _fixture(name);
      final settings = ScenarioSettings(expected);
      final projected = ScenarioSettings.fromProfile(
        settings.toProfile(UsqueProfile.defaultProfile()),
      ).toMap();
      expect(projected.keys.toSet(), expected.keys.toSet());
      expect(_canonical(projected, expected), expected);
    });
  }
}
